const data = $input.item.json;
const chaka = data.sites.chakaFarms;
const mucheru = data.sites.mucheruGolf;

// 1. Dairy Milk Calculations in Litres (Gross - Deductions = Net)
const morningYield = chaka.dairy.morningYield || 0;
const eveningYield = chaka.dairy.eveningYield || 0;
const grossMilk = morningYield + eveningYield;
const goatRation = chaka.dairy.goatRation || 0;
const gladysAlloc = chaka.dairy.gladysAllocation || 0;
const totalDeductions = goatRation + gladysAlloc;
const netMilk = grossMilk - totalDeductions;

// 2. Heavy Machinery Calculations (Consolidated Backhoe Loader)
let totalMachineHours = 0;
let totalMachineCost = 0;
mucheru.machinery.forEach(m => {
  totalMachineHours += m.hours;
  totalMachineCost += m.cost;
});

// 3. Consolidated KPIs
const kpis = [
  {
    label: "Machinery Operations",
    value: `${totalMachineHours.toFixed(1)} Hrs`,
    subtext: `Backhoe Loader Earthmoving (KES ${totalMachineCost.toLocaleString()})`
  },
  {
    label: "Course Development",
    value: "4 Greens & Teeboxes",
    subtext: "Active on Nos. 10, 11, 14, 15, 16 & Teeboxes 4, 18"
  },
  {
    label: "Dairy Cow Milk Yield",
    value: `${grossMilk.toFixed(1)} Litres`,
    subtext: `Gross Yield • ${netMilk.toFixed(1)}L Net Balance (${totalDeductions.toFixed(1)}L Allocations)`
  },
  {
    label: "Active Project Sites",
    value: "4 Sites",
    subtext: "Mucheru Golf • Chaka Farms • Kabete • Amani"
  }
];

return [
  {
    json: {
      ...data,
      calculated: {
        grossMilk,
        netMilk,
        totalDeductions,
        totalMachineHours,
        totalMachineCost,
        kpis
      }
    }
  }
];

